#!/usr/bin/env node
/**
 * 0.1.7 Preset 产物生成器（票据 07；计划 §3.5、§6 P0 载体行）。
 *
 * 背景（C0 ④）：0.1.7 起宿主不再读取 `$DSH_HOME/.agent-presets/<id>/` 目录形态，
 * 预设定居为「插件组合包（bundle）里的一条 `@deepseek-ai/dsh-agent-preset` 声明行」。
 * 真源仍是 `presets/minimal-plus/`：本模块把 `preset.yml`（展示元数据）与
 * `agent.cordis.yml`（条目列表）生成成一个自包含 bundle：
 *
 *   generated/minimal-plus-preset/
 *     package.json          dsh.bundle.patch 指向 cordis.patch.yml
 *     cordis.patch.yml      insert → agent-preset-registry 行 + preset-minimal-plus 行
 *     <plugin>.mjs          自研插件文件（逐字节复制）
 *     source-manifest.json  真源文件 sha256（产物指纹对账用）
 *
 * 解析取舍：不引入 YAML 依赖。`preset.yml` 是受控的扁平三键文件，用逐行解析并对
 * 未知行报错；`agent.cordis.yml` 用文本缩进搬运，保留注释与 `!!js` 表达式原文。
 *
 * 相对插件名改写：声明行的 `config.plugins` 由 registry 用自己的 baseUrl（profile 根）
 * 解析，因此 `./tool-bootstrap.mjs` 这类相对名必须改写成 bundle 包的子路径
 * `@dsh-plugins/minimal-plus-preset/tool-bootstrap.mjs`，安装后才解析得到。
 */
import { createHash } from "node:crypto";
import { copyFileSync, existsSync, lstatSync, mkdirSync, readFileSync, readdirSync, readlinkSync, rmSync, statSync, symlinkSync, writeFileSync } from "node:fs";
import { basename, dirname, join, resolve } from "node:path";

/** 生成 bundle 的包名；`config.plugins` 的相对名按本包名改写成子路径。 */
export const BUNDLE_PACKAGE_NAME = "@dsh-plugins/minimal-plus-preset";
/** 仓库内生成产物目录（相对仓库根）。 */
export const BUNDLE_OUT_DIR = "generated/minimal-plus-preset";
/** 真源目录（相对仓库根）。 */
export const BUNDLE_SOURCE_DIR = "presets/minimal-plus";
/** 复制进 bundle 的自研插件文件（含被上面文件相对导入的模块）。 */
export const BUNDLE_PLUGIN_FILES = [
  "tool-bootstrap.mjs",
  "phase-swap-bash.mjs",
  "instruction-hint.mjs",
  "skill-search.mjs",
  "custom-bash.mjs",
  "compaction-epoch.mjs",
  "plugin-teardown.mjs",
];
/** 真源必须齐备的文件（生成/装载前置检查共用同一份清单）。 */
export const PRESET_SOURCE_REQUIREMENTS = ["agent.cordis.yml", "preset.yml", ...BUNDLE_PLUGIN_FILES];
const MANIFEST_SCHEMA = "dsh-plugins/agent-preset-bundle-source/1";

function sha256Buffer(data) {
  return createHash("sha256").update(data).digest("hex");
}

/** 文件 sha256；不存在返回 undefined。 */
export function sha256File(path) {
  if (!existsSync(path)) return undefined;
  return sha256Buffer(readFileSync(path));
}

/**
 * 解析 `preset.yml`（受控扁平三键：name / description / order）。
 * 未知键或无法解析的行直接抛错——静默丢元数据会让生成产物缺字段。
 */
export function readPresetMeta(sourceDir) {
  const path = join(sourceDir, "preset.yml");
  const meta = {};
  for (const [index, rawLine] of readFileSync(path, "utf8").split("\n").entries()) {
    const line = rawLine.trim();
    if (line.length === 0 || line.startsWith("#")) continue;
    const match = /^(name|description|order):\s*(.*)$/u.exec(line);
    if (match === null) throw new Error(`preset.yml:${String(index + 1)}: unsupported line: ${rawLine}`);
    const [, key, value] = match;
    if (key === "order") {
      const order = Number(value);
      if (!Number.isSafeInteger(order)) throw new Error(`preset.yml: order must be an integer (got ${value})`);
      meta.order = order;
    } else {
      meta[key] = value;
    }
  }
  for (const key of ["name", "description", "order"]) {
    if (meta[key] === undefined) throw new Error(`preset.yml: missing ${key}`);
  }
  return meta;
}

/** 相对名字 → bundle 包子路径；越出源目录（含 `..`）报错而不是生成坏名字。 */
export function rewritePluginName(name, packageName = BUNDLE_PACKAGE_NAME) {
  if (!name.startsWith("./") && !name.startsWith("../")) return name;
  if (name.startsWith("../")) throw new Error(`plugin name escapes the preset directory: ${name}`);
  return `${packageName}/${name.slice(2)}`;
}

/**
 * 生成声明 patch 文本：insert registry 行 + preset 行；`plugins` 用 agent.cordis.yml
 * 原文重新缩进（10 空格）并改写相对插件名，注释与 `!!js` 表达式原样保留。
 */
export function renderPresetPatch({ meta, entryListText, packageName = BUNDLE_PACKAGE_NAME, sourceLabel = BUNDLE_SOURCE_DIR }) {
  const body = entryListText
    .split("\n")
    .map((line) => {
      if (line.trim().length === 0) return "";
      const rewritten = line.replace(/^(\s*name:\s*)(['"]?)(\.\/[^'"]+)\2(\s*)$/u, (_all, prefix, _quote, raw) => `${prefix}'${rewritePluginName(raw, packageName)}'`);
      return `          ${rewritten}`;
    })
    .join("\n")
    .replace(/\n+$/u, "");
  const unresolved = body.split("\n").filter((line) => /^\s*name:\s*['"]?\.\.?\//u.test(line));
  if (unresolved.length > 0) {
    throw new Error(`agent-preset-bundle: relative plugin name could not be rewritten (trailing comment?): ${unresolved.map((line) => line.trim()).join("; ")}`);
  }
  return [
    `# Generated by scripts/agent-preset-bundle.mjs from ${sourceLabel}/. Do not edit.`,
    "# 0.1.7 carrier: a bundle patch declares the preset; the legacy directory form is not read.",
    "- insert:",
    "    # Host-scope registry: the tui/headless profiles carry no agent-preset registry of",
    "    # their own, so the bundle brings the one its declaration needs.",
    "    - id: minimal-plus-agent-preset-registry",
    "      name: '@deepseek-ai/dsh-agent-preset-registry'",
    "      config:",
    "        default: minimal-plus",
    "",
    "    - id: preset-minimal-plus",
    "      name: '@deepseek-ai/dsh-agent-preset'",
    "      config:",
    "        id: minimal-plus",
    `        name: ${JSON.stringify(meta.name)}`,
    `        description: ${JSON.stringify(meta.description)}`,
    `        order: ${String(meta.order)}`,
    "        plugins:",
    body,
    "",
  ].join("\n");
}

/** 自包含 bundle 的 manifest（无版本耦合，避免每次发版都触发再生）。 */
function renderBundleManifest(packageName) {
  return `${JSON.stringify(
    {
      name: packageName,
      version: "0.1.0",
      private: true,
      type: "module",
      description: "Generated 0.1.7 agent-preset bundle for minimal-plus. Source of truth: presets/minimal-plus/.",
      dsh: { bundle: { patch: "./cordis.patch.yml" } },
    },
    null,
    2,
  )}\n`;
}

/** 真源指纹：每个输入文件 sha256（从 sourceDir 读，记录 sourceLabel）。 */
function renderSourceManifest({ sourceDir, sourceLabel, sourceFiles }) {
  const files = {};
  for (const name of sourceFiles) {
    const sha = sha256File(join(sourceDir, name));
    if (sha === undefined) throw new Error(`preset source is missing ${name}: ${sourceDir}`);
    files[name] = sha;
  }
  return `${JSON.stringify({ schema: MANIFEST_SCHEMA, generator: "scripts/agent-preset-bundle.mjs", sourceDir: sourceLabel, sourceFiles: files }, null, 2)}\n`;
}

/** 生成产物的每个文件内容：两个生成文件 + 逐字节复制的插件 + 真源指纹。 */
function renderArtifact({ sourceDir, sourceLabel, packageName }) {
  const meta = readPresetMeta(sourceDir);
  const entryListText = readFileSync(join(sourceDir, "agent.cordis.yml"), "utf8");
  const missing = PRESET_SOURCE_REQUIREMENTS.filter((name) => !existsSync(join(sourceDir, name)));
  if (missing.length > 0) throw new Error(`preset source is missing ${missing.join(", ")}: ${sourceDir}`);
  const files = new Map([
    ["cordis.patch.yml", renderPresetPatch({ meta, entryListText, packageName, sourceLabel: sourceLabel ?? BUNDLE_SOURCE_DIR })],
    ["package.json", renderBundleManifest(packageName)],
    ["source-manifest.json", renderSourceManifest({ sourceDir, sourceLabel: sourceLabel ?? sourceDir, sourceFiles: PRESET_SOURCE_REQUIREMENTS })],
  ]);
  for (const name of BUNDLE_PLUGIN_FILES) files.set(name, readFileSync(join(sourceDir, name)));
  return { files };
}

/**
 * 生成 bundle 到 `outDir`（覆盖既有内容；调用方保证 outDir 在可写面内）。
 * @returns `{outDir, files: [{path, sha256, kind}]}`，kind 为 `generated` / `copied`。
 */
export function generatePresetBundle({ sourceDir, outDir, packageName = BUNDLE_PACKAGE_NAME, sourceLabel }) {
  const { files } = renderArtifact({ sourceDir, sourceLabel, packageName });
  rmSync(outDir, { recursive: true, force: true });
  mkdirSync(outDir, { recursive: true });
  const written = [];
  for (const [name, content] of files) {
    writeFileSync(join(outDir, name), content, { mode: 0o644 });
    written.push({ path: name, sha256: sha256Buffer(content), kind: name.endsWith(".mjs") ? "copied" : "generated" });
  }
  return { outDir, files: written, meta: readPresetMeta(sourceDir) };
}

/** 逐文件比较两个 bundle 目录；返回 `{ok, files:[{path,status,a,b}]}`。 */
function compareBundles(referenceDir, candidateDir) {
  const names = new Set();
  for (const dir of [referenceDir, candidateDir]) {
    if (!existsSync(dir)) continue;
    for (const name of readdirSync(dir)) if (statSync(join(dir, name)).isFile()) names.add(name);
  }
  const files = [...names].sort().map((name) => {
    const a = sha256File(join(referenceDir, name));
    const b = sha256File(join(candidateDir, name));
    return { path: name, a, b, status: a === undefined || b === undefined ? "missing" : a === b ? "match" : "drift" };
  });
  return { ok: files.length > 0 && files.every((file) => file.status === "match"), files };
}

/**
 * 生成到临时目录并与仓库产物目录逐文件对账（npm test / 生成器 CLI `--check` 共用）。
 * @returns `{ok, generated, comparison}`
 */
export function checkPresetBundle({ sourceDir, bundleDir, packageName = BUNDLE_PACKAGE_NAME, sourceLabel, tempDir }) {
  const scratch = join(tempDir, `${basename(bundleDir)}.check-${String(process.pid)}-${Date.now().toString(36)}`);
  try {
    const generated = generatePresetBundle({ sourceDir, outDir: scratch, packageName, sourceLabel });
    const comparison = compareBundles(bundleDir, scratch);
    return { ok: comparison.ok, generated, comparison };
  } finally {
    rmSync(scratch, { recursive: true, force: true });
  }
}

/** node_modules 是符号链接时就地物化成真目录（render-real 的真实 profile 情形）。 */
function materializeNodeModules(nodeModules) {
  // lstat：statSync 会跟随链接，isSymbolicLink() 永远为 false，会把 @scope 目录
  // 直接 mkdir 进链接目标（真实 profile 的 node_modules）——渲染副本必须零写入源。
  if (!lstatSync(nodeModules).isSymbolicLink()) return;
  const target = resolve(dirname(nodeModules), readlinkSync(nodeModules));
  const entries = readdirSync(target);
  rmSync(nodeModules, { recursive: true, force: true });
  mkdirSync(nodeModules, { recursive: true });
  for (const entry of entries) symlinkSync(join(target, entry), join(nodeModules, entry));
}

/** profile 包清单里确保选择 bundle（幂等；保留其它字段）。 */
function ensureBundleSelected(profileDir, packageName) {
  const manifestPath = join(profileDir, "package.json");
  const manifest = existsSync(manifestPath) ? JSON.parse(readFileSync(manifestPath, "utf8")) : { name: `dsh-profile-${basename(profileDir)}`, private: true };
  manifest.dsh ??= {};
  manifest.dsh.profile ??= {};
  const bundles = manifest.dsh.profile.bundles ?? [];
  if (!bundles.includes(packageName)) bundles.push(packageName);
  manifest.dsh.profile.bundles = bundles;
  mkdirSync(profileDir, { recursive: true });
  writeFileSync(manifestPath, `${JSON.stringify(manifest, null, 2)}\n`);
}

/**
 * 把一个已存在的 bundle 目录接进隔离 profile：node_modules 链接 + `dsh.profile.bundles`
 * 选择。bundle 落在 profile 目录内（preset-bundles/）时，运行时解析的拦截层覆盖得到，
 * 插件文件的裸包导入因此可解析；node_modules 若是符号链接（真实 profile 情形）就物化
 * 成真目录，不向链接目标写任何东西。
 */
export function wireBundleIntoProfile({ profileDir, bundleDir, packageName = BUNDLE_PACKAGE_NAME }) {
  const targetDir = join(profileDir, "preset-bundles", basename(packageName));
  if (resolve(targetDir) !== resolve(bundleDir)) copyBundle(bundleDir, targetDir);
  ensureBundleSelected(profileDir, packageName);

  const nodeModules = join(profileDir, "node_modules");
  if (existsSync(nodeModules)) materializeNodeModules(nodeModules);
  else mkdirSync(nodeModules, { recursive: true });
  const linkPath = join(nodeModules, packageName);
  mkdirSync(dirname(linkPath), { recursive: true });
  rmSync(linkPath, { recursive: true, force: true });
  symlinkSync(targetDir, linkPath, "dir");
  return { bundleDir: targetDir, linkPath };
}

/**
 * 把仓库真源生成 bundle 并接进隔离 profile（smoke / 闸门 / render-real / sync 共用）。
 * @returns `{bundleDir, linkPath}`（均为 profile 目录内路径）。
 */
export function stagePresetBundle({ sourceDir, profileDir, packageName = BUNDLE_PACKAGE_NAME, sourceLabel }) {
  const bundleDir = join(profileDir, "preset-bundles", basename(packageName));
  generatePresetBundle({ sourceDir, outDir: bundleDir, packageName, sourceLabel });
  return wireBundleIntoProfile({ profileDir, bundleDir, packageName });
}

/** 把已生成的 bundle 目录接进隔离 profile（仓库根冒烟直接装入库产物时用）。 */
export function stageBundleArtifact({ artifactDir, profileDir, packageName = BUNDLE_PACKAGE_NAME }) {
  return wireBundleIntoProfile({ profileDir, bundleDir: artifactDir, packageName });
}

/** 递归复制 bundle 目录（sync `--write` 与测试共用；逐文件覆盖）。 */
export function copyBundle(sourceDir, targetDir) {
  rmSync(targetDir, { recursive: true, force: true });
  mkdirSync(targetDir, { recursive: true });
  for (const name of readdirSync(sourceDir)) {
    const from = join(sourceDir, name);
    if (!statSync(from).isFile()) continue;
    copyFileSync(from, join(targetDir, name));
  }
}
